draw:
var m = 2.0;
var E = p.energy;
function Uf(x) { return 4*x*x - x*x*x*x; }
function Ff(x) { return -(8*x - 4*x*x*x); }

var dt = 0.002;
var v0 = Math.sqrt(2*E/m);
var xs = 0, vs = v0, crossings = 0, T = 0, i, xp;
for (i = 0; i < 8000; i++) {
  xp = xs;
  vs = vs + Ff(xs)/m*dt;
  xs = xs + vs*dt;
  T = T + dt;
  if (xp > 0 && xs <= 0) crossings = crossings + 1;
  if (xp < 0 && xs >= 0) crossings = crossings + 1;
  if (crossings >= 2) break;
  if (Math.abs(xs) > 2.35) break;
}
var tm = t - T*Math.floor(t/T);
var x = 0, v = v0;
var n = Math.floor(tm/dt);
for (i = 0; i < n; i++) { v = v + Ff(x)/m*dt; x = x + v*dt; }

var xmin = -2.35, xmax = 2.35, Umin = -6, Umax = 7;
var L = W*0.10, R = W*0.04, Tp = H*0.10, B = H*0.86;
function PX(q) { return L + (q - xmin)/(xmax - xmin)*(W - L - R); }
function PY(q) { return B - (q - Umin)/(Umax - Umin)*(B - Tp); }

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

// axes
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(L, PY(0)); ctx.lineTo(W - R, PY(0)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(PX(0), Tp); ctx.lineTo(PX(0), B); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("x (m)", W - R - 34, PY(0) + 14);
ctx.fillText("U (J)", PX(0) + 6, Tp + 4);

// U(x)
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
for (i = 0; i <= 200; i++) {
  var xq = xmin + (xmax - xmin)*i/200;
  var yq = Uf(xq);
  if (yq < Umin) yq = Umin;
  if (yq > Umax) yq = Umax;
  if (i === 0) ctx.moveTo(PX(xq), PY(yq)); else ctx.lineTo(PX(xq), PY(yq));
}
ctx.stroke();

// energy line
ctx.strokeStyle = C.accent;
ctx.setLineDash([5, 4]);
ctx.beginPath(); ctx.moveTo(L, PY(E)); ctx.lineTo(W - R, PY(E)); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.accent;
ctx.fillText("E = " + E.toFixed(1) + " J", L + 4, PY(E) - 6);

// barrier top
ctx.fillStyle = C.faint;
ctx.fillText("barrier top U = 4.0 J", PX(1.41) + 6, PY(4) - 6);

// turning points
if (E < 4) {
  var xt = Math.sqrt(2 - Math.sqrt(4 - E));
  ctx.strokeStyle = C.rule;
  ctx.setLineDash([2, 4]);
  ctx.beginPath(); ctx.moveTo(PX(xt), PY(E)); ctx.lineTo(PX(xt), PY(0)); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(PX(-xt), PY(E)); ctx.lineTo(PX(-xt), PY(0)); ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = C.ink;
  ctx.fillText("turning point", PX(xt) + 5, PY(0) + 26);
}

// particle riding the curve
var px = PX(x), py = PY(Uf(x));
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(px, py, 6, 0, Math.PI*2); ctx.fill();

// kinetic energy bar from curve up to E
if (Uf(x) < E) {
  ctx.strokeStyle = C.accent;
  ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(px, PY(E)); ctx.stroke();
  ctx.fillStyle = C.ink;
  ctx.fillText("K", px + 7, (py + PY(E))/2 + 4);
}

var K = E - Uf(x);
if (K < 0) K = 0;
out.note = "U = " + Uf(x).toFixed(2) + " J, K = " + K.toFixed(2) + " J, speed = " + Math.sqrt(2*K/m).toFixed(2) + " m/s" + (E >= 4 ? "  (E is above the 4.0 J barrier: the particle escapes)" : "");
